css:
@import url("https://fonts.googleapis.com/css2?family=Cairo:wght@400;600;700&display=swap");

.soa-wrap { font-family: "Cairo", sans-serif; direction: rtl; text-align: right; color: #222; font-size: 12px; }

.soa-header { text-align: center; margin-bottom: 4mm; padding-bottom: 3mm; border-bottom: 2px solid #2c3e50; }
.soa-company { font-size: 18px; font-weight: 700; color: #2c3e50; margin-bottom: 1mm; }
.soa-company-meta { font-size: 10px; font-weight: 600; color: #555; margin-bottom: 2mm; }
.soa-title { font-size: 15px; font-weight: 700; margin: 2mm auto; padding: 2mm; background-color: #f0f0f0; border: 1.5px solid #2c3e50; display: inline-block; min-width: 60%; }

.soa-info { display: grid; grid-template-columns: repeat(4, 1fr); gap: 2mm; margin: 3mm 0; }
.soa-info-box { padding: 2mm; border-bottom: 1px solid #ccc; }
.soa-info-label { font-weight: 700; color: #555; font-size: 10px; margin-bottom: 1mm; }
.soa-info-value { font-weight: 600; font-size: 12px; color: #2c3e50; }

.soa-table { width: 100%; border-collapse: collapse; font-size: 11px; margin-top: 2mm; }
.soa-table th { background-color: #dceeff; color: #000; padding: 2mm 1mm; text-align: center; font-weight: 700; border: 1px solid #2c3e50; font-size: 11px; }
.soa-table td { padding: 1.5mm 1mm; text-align: center; border: 1px solid #666; font-size: 11px; vertical-align: middle; font-weight: 600; }
.soa-table td.txt { text-align: right; padding-right: 2mm; }
.soa-table td.num { text-align: left; padding-left: 2mm; font-family: "Cairo", monospace; white-space: nowrap; }
.soa-table tbody tr:nth-child(even) { background-color: #f9f9f9; }

.soa-row-opening td { background-color: #e8f5e9 !important; font-weight: 700; color: #1b5e20; border-top: 2px solid #28a745; border-bottom: 2px solid #28a745; }
.soa-row-total td { background-color: #2c3e50 !important; color: #fff !important; font-weight: 700; font-size: 12px; }
.soa-row-detail td { background-color: #fcfcfc !important; color: #666; font-size: 10px; font-style: italic; }
.soa-detail-label { padding-right: 8mm !important; }

.soa-footer { text-align: center; font-size: 10px; color: #777; padding-top: 2mm; margin-top: 4mm; border-top: 1px solid #ccc; }

@media print {
  .soa-table th, .soa-table td { border: 0.8px solid #000 !important; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
  .soa-table th { background-color: #dceeff !important; }
  .soa-row-opening td { background-color: #e8f5e9 !important; }
  .soa-row-total td { background-color: #2c3e50 !important; color: #fff !important; }
  .soa-table tbody tr:nth-child(even) { background-color: #f9f9f9 !important; }
}

html:
{%
  function fmt(v) {
    if (v === "" || v === null || v === undefined) return "";
    return format_currency(v, filters.company_currency || "");
  }
  function fdate(d) {
    if (!d) return "";
    return frappe.datetime.str_to_user(d);
  }
  function vtype(v) {
    if (v === "Sales Invoice") return "فاتورة مبيعات";
    if (v === "Purchase Invoice") return "فاتورة مشتريات";
    if (v === "Payment Entry") return "سند دفع";
    if (v === "Journal Entry") return "قيد يومية";
    if (v === "Sales Order") return "أمر مبيعات";
    if (v === "Purchase Order") return "أمر مشتريات";
    if (v === "Delivery Note") return "إشعار تسليم";
    return v || "";
  }
%}
<div class="soa-wrap">
  <div class="soa-header">
    {% if (typeof letter_head !== "undefined" && letter_head) { %}
      {%= letter_head %}
    {% } else { %}
      <div class="soa-company">{%= filters.company || "" %}</div>
    {% } %}
    <div class="soa-company-meta">شركة ماتش سيستمز لحلول الأنظمة التكنولوجية</div>
    <div class="soa-title">كشف حساب المورد</div>
  </div>

  <div class="soa-info">
    <div class="soa-info-box">
      <div class="soa-info-label">المورد</div>
      <div class="soa-info-value">{%= filters.supplier || "" %}</div>
    </div>
    <div class="soa-info-box">
      <div class="soa-info-label">الشركة</div>
      <div class="soa-info-value">{%= filters.company || "" %}</div>
    </div>
    <div class="soa-info-box">
      <div class="soa-info-label">من تاريخ</div>
      <div class="soa-info-value">{%= fdate(filters.from_date) %}</div>
    </div>
    <div class="soa-info-box">
      <div class="soa-info-label">إلى تاريخ</div>
      <div class="soa-info-value">{%= fdate(filters.to_date) %}</div>
    </div>
  </div>

  <table class="soa-table">
    <thead>
      <tr>
        <th style="width: 11%;">التاريخ</th>
        <th style="width: 13%;">نوع المستند</th>
        <th style="width: 15%;">رقم المستند</th>
        <th style="width: 24%;">البيان</th>
        <th style="width: 11%;">مدين</th>
        <th style="width: 11%;">دائن</th>
        <th style="width: 15%;">الرصيد</th>
      </tr>
    </thead>
    <tbody>
      {% for (var i = 0; i < data.length; i++) { %}
        {% var row = data[i]; %}
        {% var cls = ""; %}
        {% if (row.is_opening) { cls = "soa-row-opening"; } %}
        {% if (row.is_total) { cls = "soa-row-total"; } %}
        {% if (row.is_detail) { cls = "soa-row-detail"; } %}
        <tr class="{%= cls %}">
          <td>{%= fdate(row.posting_date) %}</td>
          <td>{%= vtype(row.voucher_type) %}</td>
          <td>{%= row.voucher_no || "" %}</td>
          <td class="txt {% if (row.is_detail) { %}soa-detail-label{% } %}">{%= row.remarks || "" %}</td>
          <td class="num">{%= row.debit ? fmt(row.debit) : "" %}</td>
          <td class="num">{%= row.credit ? fmt(row.credit) : "" %}</td>
          <td class="num">{%= (row.balance === "" || row.balance === undefined) ? "" : fmt(row.balance) %}</td>
        </tr>
      {% } %}
    </tbody>
  </table>

  <div class="soa-footer">
    {% if (typeof footer !== "undefined" && footer) { %}{%= footer %}{% } %}
  </div>
</div>
